this.FCVIS= function()
{
	if(this.context.binding.get("value").get("amountAdvanced") > 0)
		this.ui.get("fcPanel").setVisible(true);
	else
		this.ui.get("fcPanel").setVisible(false,true);

}

//On change of Charges and collections account - set the data below each account.
this.setAccountData = function (name) {
    var accountNum = this.context.binding.get("value").get(`${name}`);

	if(accountNum == null || accountNum == "" || accountNum == undefined) return;
    for (var i = 0; i < this.context.binding.get("value").get("accountObjList").length(); i++) {
        if (this.context.binding.get("value").get("accountObjList").get(i).get("accountNO") == accountNum) {

		var Ccy = this.context.binding.get("value").get("accountObjList").get(i).get("currencyCode");
		var balance = this.context.binding.get("value").get("accountObjList").get(i).get("balance").toString();
		var balanceSign = this.context.binding.get("value").get("accountObjList").get(i).get("balanceType")
            
            this.context.binding.get("value").set(`${name}Ccry`, Ccy);
            this.context.binding.get("value").set(`${name}Balance`, balance);
            this.context.binding.get("value").set(`${name}BalanceSign`, balanceSign);
            break;
        }
    }
}

this.setCollectableAmnt = function(val){
	if(val && val > 0 && this.context.options.collectableAmnt){
		this.context.options.collectableAmnt.set("value", val)
	}

}

//++++++++++++++++++++++++++++++++++++++++++++++Error Handling+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
this.AjaxErrorHandling = function(errorMSG)
{
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE")
}
this.setCollectionCurrency = function()
{
	//set default value
	var id = parseInt(this.context.viewid);
	id++;
	console.log("ID :",id);
	var collectionCurrency = bpmext.ui.getView("/DC_Templete1/"+id+"/Single_Select1")?.getData()?.name;
	if(collectionCurrency == null || collectionCurrency ==""){
		 bpmext.ui.getView("/DC_Templete1/"+id+"/Single_Select1").setData(this.context.binding.get("value").get("currency"));
	}
}

this.setRates = function(){
	var id = parseInt(this.context.viewid);
	id++;
	var fo = bpmext.ui.getView("/DC_Templete1/"+id);
	
	if(fo && fo?.setRate){
		
		var collectionCurrency = bpmext.ui.getView("/DC_Templete1/"+id+"/Single_Select1").getData().name;
		var requestCurrency = this.context.binding.get("value").get("currency").get("name");
		//set default value
		this.setCollectionCurrency();
		fo.setRate(collectionCurrency, requestCurrency);
	}

}
this.resetCollectionCurrency = function(){
	var id = parseInt(this.context.viewid);
	id++;
	console.log("ID :",id);
	var collectionCurrency = bpmext.ui.getView("/DC_Templete1/"+id+"/Single_Select1")?.getData().name;
	if(!!collectionCurrency ){
		 bpmext.ui.getView("/DC_Templete1/"+id+"/Single_Select1").setData(null);
		 bpmext.ui.getView("/DC_Templete1/"+id+"/Text1").setData(0.00);
		 bpmext.ui.getView("/DC_Templete1/"+id+"/negotiatedExchangeRate").setData(0.00);
	}
}
